#include <sys/socket.h>
#include <netinet/in.h>
#include <linux/ipv6.h>
#include <unistd.h>
#include <errno.h>

int setup_icmpv6_socket(struct ndp *ndp) {
    int sockfd;
    int val = 1;
    int ret;

    sockfd = socket(AF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    if (sockfd < 0) {
        return -errno;
    }

    ret = setsockopt(sockfd, SOL_IPV6, IPV6_RECVPKTINFO, &val, sizeof(val));
    if (ret < 0) {
        perror("Failed to set IPV6_RECVPKTINFO");
        close(sockfd);
        return -errno;
    }

    val = 1;
    ret = setsockopt(sockfd, SOL_IPV6, IPV6_MULTICAST_HOPS, &val, sizeof(val));
    if (ret < 0) {
        perror("Failed to set IPV6_MULTICAST_HOPS");
        close(sockfd);
        return -errno;
    }

    val = 1;
    ret = setsockopt(sockfd, SOL_IPV6, IPV6_RECVHOPLIMIT, &val, sizeof(val));
    if (ret < 0) {
        perror("Failed to set IPV6_RECVHOPLIMIT");
        close(sockfd);
        return -errno;
    }

    ndp->sockfd = sockfd;
    return 0;
}

